import { Component, computed, input } from '@angular/core';
import type { EChartsOption } from 'echarts';
import { HrmChart } from './hrm-chart';
import { chartTokenReader } from './chart-token';

/** hrm-attendance-heatmap — bản đồ nhiệt chấm công: trục X = giờ/cột, trục Y = ngày/hàng,
 *  ô đậm nhạt theo mật độ (số người có mặt, số lần quẹt thẻ…). Thấy ngay khung giờ/ngày cao điểm.
 *  Domain HRM: mật độ chấm công theo giờ, hoạt động theo ngày trong tuần, tải theo ca. */
@Component({
  selector: 'hrm-attendance-heatmap',
  imports: [HrmChart],
  template: `<hrm-chart [option]="option()" [height]="height()" />`,
  host: { class: 'hrm-attendance-heatmap' },
})
export class HrmAttendanceHeatmap {
  /** Nhãn trục X (giờ/ca). */
  readonly xLabels = input<string[]>([]);
  /** Nhãn trục Y (ngày/hàng). */
  readonly yLabels = input<string[]>([]);
  /** Dữ liệu [xIndex, yIndex, value]. */
  readonly data = input<[number, number, number][]>([]);
  readonly max = input<number | null>(null);
  readonly height = input(300);

  protected readonly option = computed<EChartsOption>(() => {
    const tk = chartTokenReader();
    // Thang màu heatmap chuyên dụng: nhạt (ít) → đậm (nhiều).
    const ramp = [tk('--seq-blue-1', '--data-2'), tk('--seq-blue-3', '--data-2'), tk('--seq-blue-5', '--data-2')].filter(Boolean);
    const maxV = this.max() ?? Math.max(...this.data().map((d) => d[2]), 1);
    return {
      tooltip: { position: 'top' },
      grid: { left: 8, right: 12, top: 8, bottom: 60, containLabel: true },
      xAxis: { type: 'category', data: this.xLabels(), splitArea: { show: true } },
      yAxis: { type: 'category', data: this.yLabels(), splitArea: { show: true } },
      visualMap: {
        min: 0, max: maxV, calculable: true, orient: 'horizontal', left: 'center', bottom: 8,
        inRange: { color: ramp },
      },
      series: [{
        type: 'heatmap', data: this.data(),
        label: { show: false },
        itemStyle: { borderColor: tk('--bg-surface', '--static-white'), borderWidth: 2, borderRadius: 3 },
      }],
    };
  });
}
